def cache_sim(capacity, ttl, ops):
    cache = {}  # key -> value
    write_time = {}  # key -> time written
    lru_order = []  # list of keys in order of use (most recent at end)
    results = []

    def is_expired(key, current_time):
        if key not in write_time:
            return True
        return current_time >= write_time[key] + ttl

    def make_most_recent(key):
        if key in lru_order:
            lru_order.remove(key)
        lru_order.append(key)

    def evict_least_recent():
        while lru_order:
            key = lru_order.pop(0)
            if key in cache and not is_expired(key, current_time):
                del cache[key]
                del write_time[key]
                return
            elif key in cache:
                del cache[key]
                del write_time[key]

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            current_time = t

            # Check if key already exists and is not expired
            if key in cache and not is_expired(key, current_time):
                # Update existing key
                cache[key] = value
                write_time[key] = t
                make_most_recent(key)
            else:
                # Adding new key
                if key in cache:
                    # Remove expired entry
                    del cache[key]
                    del write_time[key]
                    if key in lru_order:
                        lru_order.remove(key)

                # Check if we need to evict
                if len(cache) >= capacity:
                    evict_least_recent()

                # Add new entry
                cache[key] = value
                write_time[key] = t
                make_most_recent(key)

        elif op[0] == 'get':
            _, t, key = op
            current_time = t

            if key in cache and not is_expired(key, current_time):
                results.append(cache[key])
                make_most_recent(key)
            else:
                results.append(-1)

    return results

